/* ---- Type descriptor table ----
 * One static entry per type; `extc_print` exists once per program.
 * Meaning of `size`: for a scalar or struct it is sizeof(T); for an array or
 * view it is the element stride. A view always has the C layout
 * `{ T *data; int64_t len; }`.
 */
enum {
    EXTC_D_I8, EXTC_D_I16, EXTC_D_I32, EXTC_D_I64,
    EXTC_D_U8, EXTC_D_U16, EXTC_D_U32, EXTC_D_U64,
    EXTC_D_F32, EXTC_D_F64, EXTC_D_BOOL,
    EXTC_D_ENUM,      /* table = const char *const[]; the tag sits at offset 0 */
    EXTC_D_STRUCT,    /* table = ExtcField[] */
    EXTC_D_ARRAY,     /* fixed-size array: `count` elements of `elem` */
    EXTC_D_SLICE,     /* view: { T *data; int64_t len; } */
    EXTC_D_TEXT,      /* slice<u8>: printed as text, unlike any other slice */
    EXTC_D_REF        /* ref / ?ref: always printed as <ref> */
};

typedef struct ExtcDesc ExtcDesc;
typedef struct { const char *name; size_t off; const ExtcDesc *desc; } ExtcField;

struct ExtcDesc {
    int             kind;
    const char     *name;    /* display name of a struct or enum, for printing */
    size_t          size;    /* scalar/struct = sizeof(T); array/view = element stride */
    size_t          count;   /* number of fields, variants, or array elements */
    const void     *table;   /* ExtcField[] or const char *const[] */
    const ExtcDesc *elem;    /* element descriptor of an array or view */
    /* Used by structural `==`; filled in for structs only, because a struct's `==`
     * is user code (or library code) and can only be delegated to, never
     * re-derived. codegen emits a one-line adapter for it. Every other kind is
     * compared recursively by `extc_eq`, so this slot stays NULL. It sits last on
     * purpose: an initializer that omits it still zero-fills it. */
    bool          (*eq)(const void *a, const void *b);
};

/* Type-independent descriptors (reference, byte view, scalars), shared per program. */
