/* Generic recursive printer. The output format must stay byte-for-byte identical to
 * the `_debug` helpers it replaces; the truth table lives in
 * tools/print-formats.txt (floats use %g, [N]u8 prints numerically, and
 * slice<u8> prints as text). */
static void extc_print(const void *p, const ExtcDesc *d) {
    switch (d->kind) {
    case EXTC_D_I8:   printf("%d", (int)*(const int8_t *)p); return;
    case EXTC_D_I16:  printf("%d", (int)*(const int16_t *)p); return;
    case EXTC_D_I32:  printf("%d", (int)*(const int32_t *)p); return;
    case EXTC_D_I64:  printf("%lld", (long long)*(const int64_t *)p); return;
    case EXTC_D_U8:   printf("%u", (unsigned)*(const uint8_t *)p); return;
    case EXTC_D_U16:  printf("%u", (unsigned)*(const uint16_t *)p); return;
    case EXTC_D_U32:  printf("%u", (unsigned)*(const uint32_t *)p); return;
    case EXTC_D_U64:  printf("%llu", (unsigned long long)*(const uint64_t *)p); return;
    case EXTC_D_F32:  printf("%g", (double)*(const float *)p); return;
    case EXTC_D_F64:  printf("%g", (double)*(const double *)p); return;
    case EXTC_D_BOOL: printf("%s", *(const bool *)p ? "true" : "false"); return;
    case EXTC_D_REF:  printf("<ref>"); return;
    case EXTC_D_TEXT: {
        int64_t n = *(const int64_t *)((const char *)p + sizeof(void *));
        printf("%.*s", (int)n, (const char *)*(const void *const *)p);
        return;
    }
    case EXTC_D_ENUM: {
        const char *const *names = (const char *const *)d->table;
        int tag = *(const int *)p;
        if (tag < 0 || (size_t)tag >= d->count) printf("<%s>", d->name);
        else                                    printf("%s", names[tag]);
        return;
    }
    case EXTC_D_STRUCT: {
        const ExtcField *f = (const ExtcField *)d->table;
        printf("%s { ", d->name);
        for (size_t i = 0; i < d->count; i++) {
            if (i) printf(", ");
            printf("%s: ", f[i].name);
            extc_print((const char *)p + f[i].off, f[i].desc);
        }
        printf(" }");
        return;
    }
    case EXTC_D_ARRAY:
    case EXTC_D_SLICE: {
        const char *data;
        size_t n;
        if (d->kind == EXTC_D_SLICE) {
            const int64_t len = *(const int64_t *)((const char *)p + sizeof(void *));
            data = (const char *)*(const void *const *)p;
            n = len > 0 ? (size_t)len : 0;
        } else {
            data = (const char *)p;
            n = d->count;
        }
        printf("[");
        for (size_t i = 0; i < n; i++) {
            if (i) printf(", ");
            extc_print(data + i * d->size, d->elem);
        }
        printf("]");
        return;
    }
    }
}

